const bridgeCode = "// Generated by scripts/build-inline-bridge.mjs.\n// Paste above: await new Widget(Script.name(), {\n{\n  const pushVehicleState = async (snapshot, webhookUrl) => {\n    if (!isHaWebhookUrl(webhookUrl)) {\n      console.log(\"[My BMW HA] 请填写集成显示的完整 Webhook URL。\");\n      return;\n    }\n\n    const rawTimestamp = snapshot?.lastUpdatedAt;\n    const reportedAt = rawTimestamp ? new Date(rawTimestamp) : null;\n    if (!reportedAt || !Number.isFinite(reportedAt.getTime())) {\n      console.log(\"[My BMW HA] 车辆数据缺少有效的上报时间。\");\n      return;\n    }\n\n    const fuel = snapshot.combustionFuelLevel;\n    const electric = snapshot.electricChargingState;\n    const security = snapshot.doorsState?.combinedSecurityState;\n    const doorState = {\n      LOCKED: \"LOCKED\",\n      SECURED: \"LOCKED\",\n      UNLOCKED: \"UNLOCKED\",\n      SELECTIVE_LOCKED: \"UNLOCKED\",\n      PARTIALLY_LOCKED: \"UNLOCKED\",\n    }[security];\n\n    try {\n      const request = new Request(webhookUrl);\n      request.method = \"POST\";\n      request.headers = { \"Content-Type\": \"application/json\" };\n      request.timeoutInterval = 4;\n      request.onRedirect = () => null;\n      request.body = JSON.stringify({\n        version: 1,\n        reported_at: reportedAt.toISOString(),\n        battery_percent: nonnegativeNumber(electric?.chargingLevelPercent),\n        fuel_percent: nonnegativeNumber(fuel?.remainingFuelPercent),\n        fuel_range_km: nonnegativeNumber(fuel?.range),\n        electric_range_km: nonnegativeNumber(electric?.range),\n        odometer_km: nonnegativeNumber(snapshot.currentMileage),\n        door_state: doorState,\n      });\n\n      const receipt = await request.loadJSON();\n      if (request.response.statusCode !== 200) throw new Error();\n      if (receipt?.mybmw_bridge === \"updated\") {\n        console.log(\"[My BMW HA] 已更新车辆状态。\");\n      } else if (receipt?.mybmw_bridge === \"unchanged\") {\n        console.log(\"[My BMW HA] 已收到，车辆上报时间没有更新。\");\n      } else {\n        throw new Error();\n      }\n    } catch {\n      console.log(\"[My BMW HA] 未收到确认，请检查网络、Webhook 地址和车辆数据。\");\n    }\n  };\n\n  function isHaWebhookUrl(value) {\n    return /^https?:\\/\\/[^\\s/?#@\\\\]+\\/api\\/webhook\\/[a-f0-9]{64}$/.test(value);\n  }\n\n  function nonnegativeNumber(value) {\n    if (typeof value === \"string\" && value.trim() !== \"\") value = Number(value);\n    return Number.isFinite(value) && value >= 0 ? value : undefined;\n  }\n\n  const webhookKey = \"bmw-linker-ha.webhook-url.\" + Script.name();\n  const menuName = \"bmwLinkerHaWebhook\";\n  const readWebhook = () => Keychain.contains(webhookKey) ? Keychain.get(webhookKey) : \"\";\n  const webhookStatus = () => readWebhook() ? \"已设置\" : \"未设置\";\n\n  Widget = class extends Widget {\n    async getAppViewOptions() {\n      const options = await super.getAppViewOptions();\n      return {\n        ...options,\n        settingItems: [\n          {\n            name: menuName,\n            label: \"Home Assistant Webhook\",\n            type: \"cell\",\n            icon: { name: \"house.fill\", color: \"#1699cb\" },\n            needLoading: true,\n            desc: webhookStatus(),\n          },\n          ...options.settingItems,\n        ],\n        onItemClick: async (item, ...args) => {\n          if (item.name !== menuName) return options.onItemClick(item, ...args);\n\n          const alert = new Alert();\n          alert.title = \"Home Assistant Webhook\";\n          alert.message = \"粘贴 HA 集成生成的完整 Webhook URL。清空后保存可停用推送。\";\n          alert.addSecureTextField(\"Webhook URL\", readWebhook());\n          alert.addAction(\"保存\");\n          alert.addCancelAction(\"取消\");\n          if (await alert.presentAlert() === 0) {\n            const url = alert.textFieldValue(0).trim();\n            if (!url) {\n              if (Keychain.contains(webhookKey)) Keychain.remove(webhookKey);\n            } else if (isHaWebhookUrl(url)) {\n              Keychain.set(webhookKey, url);\n            } else {\n              await this.generateAlert(\"地址有误\", \"请粘贴 HA 集成显示的完整 Webhook URL。\", [\"确定\"]);\n            }\n          }\n          return { desc: { value: webhookStatus() } };\n        },\n      };\n    }\n\n    async getData(forceRefresh = false) {\n      const data = await super.getData(forceRefresh);\n      if (!forceRefresh && data?.properties && !data.black) {\n        const url = readWebhook();\n        if (url) await pushVehicleState(data.properties, url);\n      }\n      return data;\n    }\n  };\n}\n";
const configuredMenu = 'const menuName = "bmwLinkerHaWebhook";';

function scriptFolders() {
  const local = FileManager.local();
  const folders = [{ manager: local, path: local.documentsDirectory() }];
  let cloud;
  try {
    cloud = FileManager.iCloud();
    const cloudPath = cloud.documentsDirectory();
    if (cloudPath) folders.push({ manager: cloud, path: cloudPath });
  } catch {
    // The device may have iCloud Drive disabled.
  }

  const scriptDirectory = module.filename.slice(0, module.filename.lastIndexOf("/"));
  if (scriptDirectory) {
    const manager = cloud && local.isFileStoredIniCloud(module.filename) ? cloud : local;
    folders.unshift({ manager, path: scriptDirectory });
  }
  const unique = new Map();
  for (const folder of folders) {
    const key = folder.path.replace(/^\/private(?=\/var\/)/, "").replace(/\/+$/, "");
    if (!unique.has(key)) unique.set(key, folder);
  }
  return [...unique.values()];
}

function locateScript(name, folders) {
  const found = folders
    .map(({ manager, path }) => ({ manager, path: manager.joinPath(path, name + ".js") }))
    .filter(({ manager, path }) =>
      path !== module.filename && manager.fileExists(path) && !manager.isDirectory(path));
  if (found.length === 0) {
    throw new Error("找不到「" + name + "」。请输入 Scriptable 中显示的完整脚本名称。");
  }
  if (found.length > 1) {
    throw new Error("发现多份同名脚本「" + name + "」。请先给不同车辆的脚本设置不同名称。");
  }
  return { name, ...found[0] };
}

async function chooseScript() {
  const folders = scriptFolders();
  const helperNames = new Set(["bmw-linker-ha-setup", "bmw-linker-ha-bridge", "bmw-linker-ha-inline"]);
  const names = new Set();
  for (const { manager, path } of folders) {
    let files;
    try {
      if (!manager.fileExists(path)) continue;
      files = manager.listContents(path);
    } catch {
      continue;
    }
    for (const file of files) {
      if (!/^bmw-linker.*\.js$/i.test(file)) continue;
      const name = file.slice(0, -3);
      const filePath = manager.joinPath(path, file);
      if (
        !helperNames.has(name.toLowerCase()) &&
        filePath !== module.filename &&
        !manager.isDirectory(filePath)
      ) {
        names.add(name);
      }
    }
  }

  const suggested = [...names].sort((left, right) => left.localeCompare(right));
  const chooser = new Alert();
  chooser.title = "选择要安装或恢复桥接的脚本";
  for (const name of suggested) chooser.addAction(name);
  chooser.addAction("手工输入脚本名");
  chooser.addCancelAction("取消");
  const action = await chooser.presentSheet();
  if (action < 0) return null;
  if (action < suggested.length) return locateScript(suggested[action], folders);

  const prompt = new Alert();
  prompt.title = "输入 Scriptable 脚本名称";
  prompt.addTextField("例如 宝马 i4");
  prompt.addAction("继续");
  prompt.addCancelAction("取消");
  if (await prompt.presentAlert() !== 0) return null;
  const name = prompt.textFieldValue(0).trim().replace(/\.js$/i, "");
  if (!name || /[/\\\u0000-\u001f]/.test(name) || helperNames.has(name.toLowerCase())) {
    throw new Error("请输入 BMW 脚本名称，填写 Scriptable 列表里显示的名称即可。");
  }
  return locateScript(name, folders);
}

function addBridge(original) {
  if (original.includes(configuredMenu)) return original;

  // Remove the exact module call from the previous installation guide.
  const oldModuleCall = /^([ \t]*let data = await this\.getData\(\);\r?\n)[ \t]*if \(data\?\.properties && !data\.black\) \{\r?\n[ \t]*try \{\r?\n[ \t]*await importModule\("(?:bmw-linker-ha-bridge|scriptable-bridge)"\)\.pushVehicleState\(data\.properties\);\r?\n[ \t]*\} catch \{\r?\n[ \t]*console\.log\("\[My BMW HA\] 无法调用发送脚本，请检查脚本名称。"\);\r?\n[ \t]*\}\r?\n[ \t]*\}\r?\n/m;
  const updated = original.replace(oldModuleCall, "$1");
  if (/pushVehicleState|HA_WEBHOOK_URL|\[My BMW HA\]/.test(updated)) {
    throw new Error("检测到其他版本的桥接代码。安装器已保留原脚本，请先用未加桥接的 bmw-linker 运行安装。");
  }
  const startups = [...updated.matchAll(/^[ \t]*await\s+new\s+Widget\s*\(\s*Script\.name\s*\(\s*\)\s*,\s*\{/gm)];
  if (
    startups.length !== 1 ||
    !/\bclass\s+Widget\s+extends\s+BaseWidget\b/.test(updated) ||
    !/\basync\s+getAppViewOptions\s*\(/.test(updated) ||
    !/\basync\s+getData\s*\(/.test(updated)
  ) {
    throw new Error("这个 bmw-linker 版本的入口与安装器不匹配，原脚本已保留。");
  }

  const lineEnding = updated.includes("\r\n") ? "\r\n" : "\n";
  const patch = bridgeCode.replace(/\n/g, lineEnding);
  const { index } = startups[0];
  return updated.slice(0, index) + patch + lineEnding + updated.slice(index);
}

async function installBridge() {
  const script = await chooseScript();
  if (!script) return;
  const { manager, name, path } = script;
  if (manager.isFileStoredIniCloud(path)) await manager.downloadFileFromiCloud(path);
  const original = manager.readString(path);
  const updated = addBridge(original);
  if (updated === original) return "「" + name + "」已安装桥接。";

  if (manager.readString(path) !== original) {
    throw new Error("安装期间所选脚本内容发生变化，请关闭编辑器后重试。");
  }
  try {
    manager.writeString(path, updated);
    if (manager.readString(path) !== updated) throw new Error("安装校验失败");
  } catch {
    try {
      manager.writeString(path, original);
      if (manager.readString(path) !== original) throw new Error("恢复校验失败");
    } catch {
      throw new Error("写入和自动恢复失败，请重新导入原来的「" + name + "」。");
    }
    throw new Error("安装未完成，原脚本已恢复。");
  }

  return "「" + name + "」的桥接已就绪。请运行该脚本。首次安装时，在 Home Assistant Webhook 菜单设置地址；此前保存过的地址可继续使用。";
}

const result = new Alert();
try {
  result.title = "安装完成";
  result.message = await installBridge();
} catch (error) {
  result.title = "安装未完成";
  result.message = error.message;
}
if (result.message) {
  result.addAction("确定");
  await result.presentAlert();
}
